/* Real photographic home assets. No generated pixels. */
(()=>{
const prevHome=home,prevBind=bindCineInteractions;
const sources=`<details class="rp-credits"><summary>实拍影像来源与说明</summary><p>枝头实拍：Salvador Escriva，<a href="https://commons.wikimedia.org/wiki/File:Caquis_en_el_%C3%A1rbol.jpg" target="_blank" rel="noopener">Caquis en el árbol</a>；整果实拍：Rodrigo.Argenton，<a href="https://commons.wikimedia.org/wiki/File:Caqui_chocolate_em_fundo_preto_04.jpg" target="_blank" rel="noopener">Chocolate 04</a>、<a href="https://commons.wikimedia.org/wiki/File:Caqui_rama_forte_em_fundo_preto_01.jpg" target="_blank" rel="noopener">Rama forte 01</a>、<a href="https://commons.wikimedia.org/wiki/File:Caqui_rama_forte_em_fundo_preto_02.jpg" target="_blank" rel="noopener">Rama forte 02</a>。均来自 Wikimedia Commons，按 <a href="https://creativecommons.org/licenses/by-sa/4.0/" target="_blank" rel="noopener">CC BY-SA 4.0</a> 使用。图片作缩放、显示裁切、混合排布；拖动时作标明的颜色模拟，改编影像同许可。原图可在来源页取得。图片为不同品种与拍摄条件下的科普素材，不是太行山或团队采集记录，不是标准等级样本。01 与 03 为同品种不同拍摄视角。</p></details>`;
home=function(){let s=prevHome();s=s.replace('assets/orchard-close-v2.webp','assets/orchard-real-branch.webp').replace('艺术化果枝近景，三枚柿果与虚化远山','真实柿树枝头照片，多枚柿果与叶片').replace('从远山到果皮的细纹。','从一片叶，到果皮的细纹。').replace('枝头观察 / 艺术化场景','枝头观察 / 真实摄影').replace('艺术化果园场景 · 非现场采集记录','Salvador Escriva / CC BY-SA 4.0 · 非团队采集').replace('--x:68%;--y:49%','--x:62%;--y:43%').replace('--x:84%;--y:30%','--x:55%;--y:27%').replace('一枚果实。<br><em>四种秋色。</em>','几枚柿果。<br><em>一季秋色。</em>').replace('把时间交给指尖。<br>拖动色谱，观察外观颜色的变化。','保留真实的纹理与差异。<br>拖动观察色彩，移动光标放大细节。');
let a=s.indexOf('<div class="hf-specimen-area">'),b=s.indexOf('<div class="hf-color-control">',a);
s=s.slice(0,a)+`<div class="hf-specimen-area rp-area"><span class="hf-specimen-id">DIOSPYROS KAKI / REAL PHOTOGRAPHY</span><div class="rp-specimens" aria-label="三幅柿果实拍视角，点选或移动光标放大"><button class="rp-photo rp-photo-a" data-photo="0" aria-label="放大黄橙柿果实拍"><img src="assets/persimmon-real-yellow.webp" alt="黄橙色柿果真实照片，原始色彩与纹理"><span>01 / 黄橙外观</span></button><button class="rp-photo rp-photo-b" data-photo="1" aria-label="放大橙红柿果实拍"><img src="assets/persimmon-real-red.webp" alt="橙红柿果真实照片"><span>02 / 橙红外观</span></button><button class="rp-photo rp-photo-c" data-photo="2" aria-label="放大柿果另一视角实拍"><img src="assets/persimmon-real-angle.webp" alt="柿果另一拍摄视角"><span>03 / 换个角度</span></button><div class="rp-lens" aria-hidden="true"></div></div><div class="rp-photo-toolbar"><span id="rp-lens-tip" aria-live="polite">移动光标放大 · 手机点选查看细节</span><button type="button" id="rp-original" aria-pressed="false">查看原图颜色</button></div><div class="rp-mobile-detail" hidden><button type="button" id="rp-detail-close">收起细节 ×</button><div class="rp-mobile-crop" tabindex="0" aria-label="实拍细节，可左右拖动查看"><img alt="选中照片局部放大"></div><small>原图局部 · 左右拖动查看</small></div></div>`+s.slice(b);
s=s.replace('同一果实的颜色模拟，非真实成熟过程或检测结论。','实拍照片上的颜色模拟，非真实成熟记录；网上素材不作为模型标准样本。</small>'+sources+'<small hidden>');return s};
bindCineInteractions=function(){if(route!=='home'){prevBind();return}
// Bind the retained orchard behavior without running obsolete single-fruit controls.
const root=document.getElementById('app'),orchard=root.querySelector('.hf-orchard'),world=root.querySelector('.hf-orchard-world'),copy=root.querySelector('.hf-orchard-copy'),note=root.querySelector('.hf-focus-note'),targets=root.querySelector('.hf-targets');let trigger=null;const reduced=matchMedia('(prefers-reduced-motion:reduce)').matches;
function close(){orchard.classList.remove('hf-focused');note.hidden=true;copy.inert=targets.inert=false;trigger?.focus()}
root.querySelectorAll('[data-focus]').forEach(b=>b.onclick=()=>{trigger=b;let i=+b.dataset.focus,mobile=matchMedia('(max-width:760px)').matches;world.style.setProperty('--focus-x',mobile?'60%':i?'55%':'62%');world.style.setProperty('--focus-y',i?'27%':'43%');orchard.classList.add('hf-focused');note.hidden=false;copy.inert=targets.inert=true;note.querySelector('h3').textContent=i?'一片叶，也会遮住线索。':'看颜色，也看差异。';note.querySelector('p').textContent=i?'真实果园中，叶片与果实互相遮挡。采集时尽量让目标完整入镜。':'同一枝头也有明暗与着色差异。颜色提供外观线索，不等于内部品质。';note.querySelector('button').focus()});root.querySelector('.hf-return').onclick=close;orchard.onkeydown=e=>{if(e.key==='Escape')close()};
if(!reduced&&matchMedia('(pointer:fine)').matches){orchard.onpointermove=e=>{if(!note.hidden)return;let r=orchard.getBoundingClientRect();orchard.style.setProperty('--px',((e.clientX-r.left)/r.width-.5)*10+'px');orchard.style.setProperty('--py',((e.clientY-r.top)/r.height-.5)*6+'px')};orchard.onpointerleave=()=>{orchard.style.setProperty('--px','0px');orchard.style.setProperty('--py','0px')}}
const area=root.querySelector('.rp-specimens'),lens=root.querySelector('.rp-lens'),photos=[...root.querySelectorAll('.rp-photo')],range=root.querySelector('#hf-ripeness'),original=root.querySelector('#rp-original');let real=false,selected=1;const names=['未熟','转色期','着色期','完熟'],notes=['青绿色外观线索；这里是实拍照片上的调色示意。','黄绿转向黄橙，注意局部颜色分布。','橙色逐渐铺开；品种与光照也会影响外观。','深色外观仍不能说明糖度、脱涩或适口性。'];
function apply(){let v=+range.value,k=Math.round(v),filter=real?'none':`hue-rotate(${v<=2?(2-v)*30:-(v-2)*8}deg) saturate(${.65+v*.14}) brightness(1.12)`;photos.forEach(p=>p.querySelector('img').style.filter=filter);lens.style.filter=filter;root.querySelector('#hf-stage-number').textContent='0'+(k+1);root.querySelector('#hf-stage-name').textContent=real?'原图颜色':names[k];root.querySelector('#hf-stage-label').textContent=real?'原图颜色':names[k];root.querySelector('#hf-stage-copy').textContent=real?'保留来源照片的真实色彩；不对网络照片作等级判定。':notes[k];range.setAttribute('aria-valuetext',names[k]+'，颜色模拟');root.querySelectorAll('[data-stage]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.stage===k&&!real)));original.setAttribute('aria-pressed',String(real));original.textContent=real?'返回颜色模拟':'查看原图颜色'}
function simulate(){real=false;apply()}range.oninput=simulate;range.onchange=()=>{range.value=Math.round(+range.value);simulate()};root.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{range.value=b.dataset.stage;simulate()});original.onclick=()=>{real=!real;apply()};apply();
function magnify(p,e){let im=p.querySelector('img'),r=im.getBoundingClientRect(),a=area.getBoundingClientRect();let x=e?Math.max(0,Math.min(r.width,e.clientX-r.left)):r.width*.5,y=e?Math.max(0,Math.min(r.height,e.clientY-r.top)):r.height*.5;const size=lens.offsetWidth||150,z=2.25;lens.style.backgroundImage=`url("${im.getAttribute('src')}")`;lens.style.backgroundSize=`${r.width*z}px ${r.height*z}px`;lens.style.backgroundPosition=`${size/2-x*z}px ${size/2-y*z}px`;lens.style.left=Math.max(size/2,Math.min(a.width-size/2,r.left-a.left+x))+'px';lens.style.top=Math.max(size/2,Math.min(a.height-size/2,r.top-a.top+y))+'px';lens.classList.add('visible');photos.forEach(b=>b.classList.toggle('rp-active',b===p));}
const detail=root.querySelector('.rp-mobile-detail'),crop=root.querySelector('.rp-mobile-crop');photos.forEach(p=>{p.onpointermove=e=>{if(e.pointerType==='mouse')magnify(p,e)};p.onpointerleave=()=>lens.classList.remove('visible');p.onfocus=()=>{if(matchMedia('(pointer:fine)').matches)magnify(p)};p.onblur=()=>lens.classList.remove('visible');p.onclick=()=>{selected=+p.dataset.photo;if(matchMedia('(pointer:fine)').matches&&!matchMedia('(max-width:760px)').matches){magnify(p);return}detail.hidden=false;detail.querySelector('img').src=p.querySelector('img').getAttribute('src');detail.querySelector('img').style.objectPosition='50% 50%';root.querySelector('#rp-detail-close').focus()}});root.querySelector('#rp-detail-close').onclick=()=>{detail.hidden=true;photos[selected].focus()};detail.onkeydown=e=>{if(e.key==='Escape')root.querySelector('#rp-detail-close').click()};let drag;crop.onpointerdown=e=>{drag=e.clientX;crop.setPointerCapture(e.pointerId)};crop.onpointermove=e=>{if(drag!==undefined)crop.querySelector('img').style.objectPosition=Math.max(0,Math.min(100,50+(e.clientX-drag)/3))+'% 50%'};crop.onpointerup=crop.onpointercancel=()=>drag=undefined;
};
})();
